import sys
import lzma

CONFIGS = [(4, 0, 0), (3, 0, 0), (3, 0, 2), (2, 0, 0)]


def filters(lc, lp, pb):
    return [{"id": lzma.FILTER_LZMA2, "preset": 9 | lzma.PRESET_EXTREME, "lc": lc, "lp": lp, "pb": pb, "dict_size": 1 << 24}]


def main():
    if len(sys.argv) != 2 or sys.argv[1] not in ("c", "d"):
        sys.stderr.write("usage: squeeze.py c|d\n")
        sys.exit(2)
    data = sys.stdin.buffer.read()
    if sys.argv[1] == "c":
        best = None
        for i, (lc, lp, pb) in enumerate(CONFIGS):
            c = lzma.compress(data, format=lzma.FORMAT_RAW, filters=filters(lc, lp, pb))
            if best is None or len(c) < len(best[1]):
                best = (i, c)
        out = bytes([best[0]]) + best[1]
    else:
        i = data[0]
        lc, lp, pb = CONFIGS[i]
        out = lzma.decompress(data[1:], format=lzma.FORMAT_RAW, filters=filters(lc, lp, pb))
    sys.stdout.buffer.write(out)
    sys.stdout.buffer.flush()


if __name__ == "__main__":
    main()
